const fs=require('node:fs');
async function setup(browser,kind,width=390,height=844){const page=await browser.newPage({viewport:{width,height},acceptDownloads:true});await page.route('https://physical.test/**',r=>{const file=r.request().url().replace('https://physical.test/','');r.fulfill(file.startsWith('assets/')?{contentType:file.endsWith('css')?'text/css':'text/javascript',body:fs.readFileSync(file)}:{contentType:'text/html',body:'<!doctype html><meta charset="utf-8"><style>body{font-family:Arial;background:#090d16}.iv-physical-pending{color:#e2e8f0}</style><div class="member-menu-panel"><button onclick="app.openMemberSettings()">My Account</button></div><div class="admin-menu-panel"><button id="btn-my-account">My Account</button></div><div class="provider-menu-panel"></div><div id="member-profile-modal"><div class="min-w-0"></div></div>'});});await page.goto('https://physical.test/');await page.addStyleTag({path:'assets/physical-ids.css'});await page.evaluate(({kind})=>{
 const c=document.createElement('canvas');c.width=c.height=256;const x=c.getContext('2d');x.fillStyle='#d97706';x.fillRect(0,0,256,256);x.fillStyle='#111827';x.fillRect(60,50,140,160);const photo=c.toDataURL();window.card={tenant_id:'a',member_id:'one',card_id:'aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',version:1,payload:'IVC1|11111111-1111-4111-8111-111111111111',snapshot_hash:'hash',workflow_version:3,card_state:'active',member:{id:'one',name:'Alex Santos',display_code:'MEM-0001',photo,status:'ACTIVE'},gym:{name:'Test Gym',logo:photo,accent:'#0f766e',address:'1 Test Road, Manila',phone:'09000000000',email:'gym@example.test'},role:kind==='member'?'member':kind==='master'?'provider':'owner',permissions:{manage:kind!=='member',download:kind!=='member',replace:kind!=='master',create_replacement:false}};
 window.calls=[];window.authCallbacks=[];window.rows=[];window.user='user-one';window.delay=false;window.fail=false;window.failAfter=false;window.operations=new Map();window.historyRows=[1,2,3].map(n=>({id:'event'+n,created_at:new Date().toISOString(),action:'production_download_authorized',version:1,actor_id:'actor-one'}));window.IronVaultAuth={requireRole:async()=>{if(window.revoked)throw Error('Denied');return{user_id:user,role:card.role,tenant_id:'a',member_id:'one'};}};window.app={currentTenantId:'a',currentMember:{id:'one',tenantId:'a'},authenticatedRole:{user_id:user,tenant_id:'a',member_id:'one'},activeModalMemberId:'one'};
 function row(id,status,kind='initial'){return{id,tenant_id:'a',member_id:'one',card_id:card.card_id,kind,status,revision:1,version:card.version,name:'Alex Santos',display_code:'MEM-0001',updated_at:new Date().toISOString()};}
 function replacement(){card.card_id=crypto.randomUUID();card.version++;card.payload='IVC1|'+crypto.randomUUID();card.card_state='active';card.permissions.create_replacement=false;card.permissions.download=kind!=='member';card.permissions.replace=kind!=='master';delete card.loss_request_id;delete card.loss_revision;}
 window.client={auth:{onAuthStateChange:fn=>authCallbacks.push(fn)},rpc:async(name,args)=>{calls.push({name,args:structuredClone(args)});if(delay)await new Promise(r=>window.release=r);if(name==='iv_physical_ids'){const a=args.p_action;if(a==='capabilities')return window.missing?{error:{message:'Invalid physical ID query',code:'P0001'}}:{data:{workflow_version:3}};if(a==='gyms')return{data:{items:[{id:'a',name:'Test Gym',display_code:'GYM-0001'}]}};if(a==='members')return{data:{items:[{id:'one',name:'Alex Santos',display_code:'MEM-0001'}]}};if(a==='preview'||a==='loss')return{data:{...structuredClone(card),...(window.foreign?{tenant_id:'b'}:{})}};if(a==='history')return{data:{items:historyRows}};return{data:{items:structuredClone(rows)}};}
 const action=args.p_action,d=args.p_data;if(window.denyDownload&&action==='download_direct')return{error:{message:'Download permission revoked',code:'42501'}};if(fail){fail=false;return{error:{message:'Network response lost'}};}if(operations.has(d.operation_id))return{data:structuredClone(operations.get(d.operation_id))};if(d.card_id!==card.card_id)return{error:{message:'Card changed. Refresh the preview',code:'P0001'}};
 if(action==='submit')rows=[row('r1','awaiting_gym_review')];
 if(action==='report_loss'){rows.forEach(r=>r.status='obsolete');delete card.payload;card.card_state='awaiting_replacement';card.permissions.replace=false;card.permissions.download=false;card.permissions.create_replacement=kind!=='member'&&kind!=='master';const r=row('r2','awaiting_replacement','replacement');rows.unshift(r);card.loss_request_id=r.id;card.loss_revision=r.revision;}
 if(action==='create_replacement'){replacement();rows[0].card_id=card.card_id;rows[0].version=card.version;rows[0].revision++;rows[0].status='awaiting_gym_review';}
 if(action==='replace'){replacement();rows=[row('r3','awaiting_gym_review','replacement')];}
 if(action==='request_provider'){if(d.request_id){rows[0].revision++;rows[0].status='sent_to_provider';rows[0].route='provider';}else{rows=[row('r4','sent_to_provider')];rows[0].route='provider';}}
 if(action==='transition'){rows[0].status=d.status;rows[0].revision++;if(d.status==='printing_locally')rows[0].route='local';}
 const result={request_id:rows[0]?.id,card_id:card.card_id,status:rows[0]?.status,revision:rows[0]?.revision};operations.set(d.operation_id,structuredClone(result));if(failAfter){failAfter=false;return{error:{message:'Network response lost'}};}return{data:result};}};
 },{kind});await page.addScriptTag({path:'assets/physical-id-renderer.js'});await page.addScriptTag({path:'assets/physical-ids.js'});await page.evaluate(kind=>IronVaultPhysicalIDs.install(app,client,kind),kind);page.on('dialog',d=>d.accept());return page;}
module.exports={setup};
